-- Master Kenya travel keyword library with repeatable usage cycles.
CREATE TABLE IF NOT EXISTS public.content_keywords (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  keyword TEXT NOT NULL UNIQUE,
  destination TEXT,
  search_intent TEXT,
  content_type TEXT,
  priority INTEGER NOT NULL DEFAULT 1,
  times_used INTEGER NOT NULL DEFAULT 0,
  last_used_at TIMESTAMPTZ,
  locked_by_job_id UUID,
  locked_until TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS content_keywords_usage_idx ON public.content_keywords(times_used ASC, priority DESC, last_used_at ASC NULLS FIRST);
CREATE INDEX IF NOT EXISTS content_keywords_lock_idx ON public.content_keywords(locked_until);
ALTER TABLE public.content_generation_jobs ADD COLUMN IF NOT EXISTS keyword_id UUID REFERENCES public.content_keywords(id) ON DELETE SET NULL;
ALTER TABLE public.content_generation_jobs ADD COLUMN IF NOT EXISTS keyword_cycle INTEGER;
ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS target_keyword_id UUID REFERENCES public.content_keywords(id) ON DELETE SET NULL;
ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS keyword_cycle INTEGER;
CREATE INDEX IF NOT EXISTS blog_posts_target_keyword_idx ON public.blog_posts(target_keyword_id);

-- Backfill keyword relationships and usage counts from existing AI articles where focus_keyword matches the library.
UPDATE public.blog_posts p
SET target_keyword_id = ck.id,
    keyword_cycle = 1
FROM public.content_keywords ck
WHERE p.target_keyword_id IS NULL
  AND p.focus_keyword IS NOT NULL
  AND lower(trim(p.focus_keyword)) = lower(trim(ck.keyword));

UPDATE public.content_keywords ck
SET times_used = stats.use_count,
    last_used_at = stats.last_used_at,
    updated_at = now()
FROM (
  SELECT target_keyword_id, COUNT(*)::INTEGER AS use_count, MAX(created_at) AS last_used_at
  FROM public.blog_posts
  WHERE target_keyword_id IS NOT NULL
  GROUP BY target_keyword_id
) stats
WHERE ck.id = stats.target_keyword_id;
CREATE INDEX IF NOT EXISTS content_generation_jobs_keyword_idx ON public.content_generation_jobs(keyword_id);
ALTER TABLE public.content_keywords ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Content admins manage content keywords" ON public.content_keywords;
CREATE POLICY "Content admins manage content keywords" ON public.content_keywords FOR ALL TO authenticated USING (public.is_content_admin()) WITH CHECK (public.is_content_admin());
GRANT ALL ON public.content_keywords TO authenticated;
CREATE OR REPLACE FUNCTION public.claim_content_keyword(p_job_id UUID)
RETURNS public.content_keywords
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE result public.content_keywords;
BEGIN
  UPDATE public.content_keywords
  SET locked_by_job_id = p_job_id,
      locked_until = now() + interval '15 minutes',
      updated_at = now()
  WHERE id = (
    SELECT id
    FROM public.content_keywords
    WHERE (locked_until IS NULL OR locked_until < now())
    ORDER BY times_used ASC, priority DESC, last_used_at ASC NULLS FIRST, id
    FOR UPDATE SKIP LOCKED
    LIMIT 1
  )
  RETURNING * INTO result;
  IF result.id IS NULL THEN
    RAISE EXCEPTION 'No content keywords are currently available';
  END IF;
  RETURN result;
END;
$$;
CREATE OR REPLACE FUNCTION public.complete_content_keyword(p_job_id UUID, p_keyword_id UUID)
RETURNS public.content_keywords
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE result public.content_keywords;
BEGIN
  UPDATE public.content_keywords
  SET times_used = times_used + 1,
      last_used_at = now(),
      locked_by_job_id = NULL,
      locked_until = NULL,
      updated_at = now()
  WHERE id = p_keyword_id AND locked_by_job_id = p_job_id
  RETURNING * INTO result;
  IF result.id IS NULL THEN RAISE EXCEPTION 'Keyword claim not found or already released'; END IF;
  RETURN result;
END;
$$;
CREATE OR REPLACE FUNCTION public.release_content_keyword(p_job_id UUID, p_keyword_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE public.content_keywords
  SET locked_by_job_id = NULL, locked_until = NULL, updated_at = now()
  WHERE id = p_keyword_id AND locked_by_job_id = p_job_id;
END;
$$;
GRANT EXECUTE ON FUNCTION public.claim_content_keyword(UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.complete_content_keyword(UUID, UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.release_content_keyword(UUID, UUID) TO service_role;
CREATE OR REPLACE FUNCTION public.set_content_keywords_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS content_keywords_updated_at ON public.content_keywords;
CREATE TRIGGER content_keywords_updated_at BEFORE UPDATE ON public.content_keywords FOR EACH ROW EXECUTE FUNCTION public.set_content_keywords_updated_at();
